const canvas = document.querySelector("canvas");
const ctx = canvas.getContext("2d");

function fit() {
  const ratio = devicePixelRatio || 1;
  canvas.width = Math.round(innerWidth * ratio);
  canvas.height = Math.round(innerHeight * ratio);
  ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
}
fit();
still.on("resize", fit);

function hand(angle, length, width, color) {
  ctx.save();
  ctx.rotate(angle);
  ctx.beginPath();
  ctx.moveTo(0, length * 0.12);
  ctx.lineTo(0, -length);
  ctx.lineWidth = width;
  ctx.lineCap = "round";
  ctx.strokeStyle = color;
  ctx.stroke();
  ctx.restore();
}

function draw() {
  const { seconds, ticks, numbers } = still.values;
  const { accent, text } = still.theme;
  const w = innerWidth;
  const h = innerHeight;
  const r = Math.min(w, h) / 2 - 2;
  const now = new Date();
  const ms = now.getMilliseconds() / 1000;
  const s = now.getSeconds() + ms;
  const m = now.getMinutes() + s / 60;
  const hr = (now.getHours() % 12) + m / 60;
  ctx.clearRect(0, 0, w, h);
  ctx.save();
  ctx.translate(w / 2, h / 2);
  const marks = ticks === "Minutes" ? 60 : ticks === "Hours" ? 12 : 0;
  for (let i = 0; i < marks; i++) {
    const major = marks === 12 || i % 5 === 0;
    ctx.save();
    ctx.rotate((i / marks) * Math.PI * 2);
    ctx.beginPath();
    ctx.moveTo(0, -r);
    ctx.lineTo(0, -r + (major ? r * 0.1 : r * 0.05));
    ctx.lineWidth = major ? 2 : 1;
    ctx.strokeStyle = text;
    ctx.globalAlpha = major ? 0.8 : 0.35;
    ctx.stroke();
    ctx.restore();
  }
  if (numbers) {
    ctx.fillStyle = text;
    ctx.globalAlpha = 0.85;
    ctx.font = `${Math.round(r * 0.16)}px ${getComputedStyle(document.body).fontFamily}`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    for (let n = 1; n <= 12; n++) {
      const a = (n / 12) * Math.PI * 2;
      ctx.fillText(String(n), Math.sin(a) * r * 0.72, -Math.cos(a) * r * 0.72);
    }
  }
  ctx.globalAlpha = 1;
  hand((hr / 12) * Math.PI * 2, r * 0.5, Math.max(3, r * 0.05), text);
  hand((m / 60) * Math.PI * 2, r * 0.75, Math.max(2, r * 0.035), text);
  if (seconds) hand((s / 60) * Math.PI * 2, r * 0.85, 1.5, accent);
  ctx.beginPath();
  ctx.arc(0, 0, Math.max(3, r * 0.04), 0, Math.PI * 2);
  ctx.fillStyle = seconds ? accent : text;
  ctx.fill();
  ctx.restore();
  requestAnimationFrame(draw);
}
draw();

const canvas = document.querySelector("canvas");
const ctx = canvas.getContext("2d");

function fit() {
  const ratio = devicePixelRatio || 1;
  canvas.width = Math.round(innerWidth * ratio);
  canvas.height = Math.round(innerHeight * ratio);
  ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
}
fit();
still.on("resize", fit);

let bands = new Array(48).fill(0);
const shown = [];
still.on("audio", (audio) => (bands = audio.bands));

function draw() {
  const { bars, gap, mirror, rounded, falloff } = still.values;
  const w = innerWidth;
  const h = innerHeight;
  const count = Math.round(bars);
  const width = Math.max(1, (w - gap * (count - 1)) / count);
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = still.theme.accent;
  for (let i = 0; i < count; i++) {
    // Each bar shows the loudest of the bands it covers.
    const from = Math.floor((i * bands.length) / count);
    const to = Math.max(from + 1, Math.floor(((i + 1) * bands.length) / count));
    let level = 0;
    for (let b = from; b < to; b++) level = Math.max(level, bands[b]);
    shown[i] = Math.max(level, (shown[i] || 0) * falloff);
    const height = Math.max(2, shown[i] * (mirror ? h / 2 : h));
    const x = i * (width + gap);
    const y = mirror ? h / 2 - height : h - height;
    const total = mirror ? height * 2 : height;
    ctx.beginPath();
    ctx.roundRect(x, y, width, total, rounded ? Math.min(width / 2, 4) : 0);
    ctx.fill();
  }
  requestAnimationFrame(draw);
}
draw();

const canvas = document.querySelector("canvas");
const ctx = canvas.getContext("2d");

function fit() {
  const ratio = devicePixelRatio || 1;
  canvas.width = Math.round(innerWidth * ratio);
  canvas.height = Math.round(innerHeight * ratio);
  ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
}
fit();
still.on("resize", fit);

let wave = new Array(128).fill(0);
let shown = wave.slice();
still.on("audio", (audio) => (wave = audio.wave));

function draw() {
  const { thickness, gain, glow, fill } = still.values;
  const w = innerWidth;
  const h = innerHeight;
  ctx.clearRect(0, 0, w, h);
  // Ease toward the newest samples so the line doesn't jitter.
  shown = shown.map((v, i) => v + ((wave[i] || 0) - v) * 0.5);
  const y = (v) => h / 2 - Math.max(-1, Math.min(1, v * gain)) * (h / 2 - thickness);
  ctx.beginPath();
  shown.forEach((v, i) => {
    const x = (i / (shown.length - 1)) * w;
    if (i === 0) ctx.moveTo(x, y(v));
    else ctx.lineTo(x, y(v));
  });
  ctx.lineJoin = "round";
  ctx.lineWidth = thickness;
  ctx.strokeStyle = still.theme.accent;
  ctx.shadowColor = still.theme.accent;
  ctx.shadowBlur = glow ? 10 : 0;
  ctx.stroke();
  if (fill) {
    ctx.lineTo(w, h / 2);
    ctx.lineTo(0, h / 2);
    ctx.closePath();
    ctx.globalAlpha = 0.18;
    ctx.fillStyle = still.theme.accent;
    ctx.fill();
    ctx.globalAlpha = 1;
  }
  requestAnimationFrame(draw);
}
draw();
